// site.options.ts
const link = { fields: { label: { default: '', required: true }, href: { default: '/' } } };

export const siteOptions = {
	contentDir: 'content',
	globals: {
		banner: { label: 'Site banner', meta: { message: { default: '' }, visible: { default: false } } },
		menus: { meta: { header: { default: [] as { label: string; href: string }[], list: link } } }
	}
} satisfies SiteOptions;

// src/routes/+layout.server.ts
import { loadGlobal } from 'uncial-cms';
import { site } from '$lib/site.js';

export const load = async () => ({ banner: await loadGlobal(site, 'banner') });

// site.options.ts
collections: {
	states: { dir: 'data/states', label: 'States', meta: { name: { default: '', required: true }, capital: { default: '' } } }
}

// src/routes/states/+page.server.ts
export const load = async () => ({ states: await loadCollection(site, 'states') });
